insert into public.waypoints
  (id, trail_id, type, name, name_fil, note, latitude, longitude, elevation_m, position, distance_m)
values
  ('batulao-new-trail-01-jump-off', 'batulao-new-trail', 'jump_off', 'Batulao jump-off', 'Jump-off ng Batulao',
   'OSM highway=trailhead "Batulao Jumpoff" at the end of Batulao Trail Road. The registration booth (OSM shop=ticket, node 6389746485) is about 120 m before it on the same road.',
   14.0554825, 120.8205722, 599, 1, 0),
  ('batulao-new-trail-02-campsite', 'batulao-new-trail', 'campsite', 'Peak 8 campsite', 'Kampuhan sa Peak 8',
   'The New Trail''s campsite and fee checkpoint. Some trip reports call it "Camp 8"; it is not the Old Trail''s Camp 8 near the summit.',
   14.0456747, 120.802914, null, 2, 2517),
  ('batulao-new-trail-03-summit', 'batulao-new-trail', 'summit', 'Mt. Batulao summit', 'Tuktok ng Bundok Batulao',
   '811 m (OSM ele). Camping at the summit is reported as not allowed.',
   14.0399434, 120.8023782, 811, 3, 3389),
  ('batulao-old-trail-01-jump-off', 'batulao-old-trail', 'jump_off', 'Batulao jump-off', 'Jump-off ng Batulao',
   'Shared with the New Trail up to the fork past the kubo stores.',
   14.0554825, 120.8205722, 599, 1, 0),
  ('batulao-old-trail-02-water', 'batulao-old-trail', 'water', 'Spring east of Camp 1', 'Bukal sa silangan ng Camp 1',
   'OSM natural=spring, off the path. Reported seasonal and not reliably safe: treat or filter before drinking.',
   14.0439882, 120.8079189, 561, 2, 3131),
  ('batulao-old-trail-03-water', 'batulao-old-trail', 'water', 'Spring at Camp 1', 'Bukal sa Camp 1',
   'OSM natural=spring beside Camp 1. Reported seasonal and not reliably safe: treat or filter before drinking.',
   14.043605, 120.8070758, null, 3, 3255),
  ('batulao-old-trail-04-campsite', 'batulao-old-trail', 'campsite', 'Camp 1', 'Camp 1 (kampuhan)',
   'The designated campsite at the foot of the Old Trail: the largest tent area, with toilets and a store reported.',
   14.0435188, 120.8071103, 576, 4, 3264),
  ('batulao-old-trail-05-summit', 'batulao-old-trail', 'summit', 'Mt. Batulao summit', 'Tuktok ng Bundok Batulao',
   '811 m (OSM ele). The last section from Camp 9 is steep, with fixed ropes.',
   14.0399434, 120.8023782, 811, 5, 4177);

insert into public.reference_passages
  (id, destination_id, topic, language, text, source, sources, as_of)
values
  ('batulao-getting-there-1-en', 'batulao', 'getting_there', 'en',
   'Mt. Batulao''s jump-off is in Nasugbu, Batangas, off the Tagaytay–Nasugbu road. Commuters take a Nasugbu-bound bus, ask to be dropped at KC Hillcrest Golf Club (formerly Evercrest), then ride a tricycle or walk to the registration area. A 2022 trip report gave the bus ride from Manila as 2 to 3 hours. OpenStreetMap puts the summit about 3.4 km from the jump-off by the New Trail and 4.2 km by the Old Trail.',
   'transitpinas.com (2022), lakbaypinas.com (2026), openstreetmap.org (2026)',
   '[{"title": "Mt. Batulao, Batangas | Into the Jagged Peaks of Nasugbu (TransitPinas)", "url": "https://transitpinas.com/batulao-nasugbu-batangas/", "published": "2022-07-07", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "OpenStreetMap: Mt. Batulao relation 3350629 and nearby nodes (Overpass, data as of 2026-10-09)", "url": "https://www.openstreetmap.org/relation/3350629", "published": "2026-10-09", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-getting-there-1-fil', 'batulao', 'getting_there', 'fil',
   'Nasa Nasugbu, Batangas ang jump-off ng Bundok Batulao, malapit sa Tagaytay–Nasugbu road. Kung magko-commute, sumakay ng bus papuntang Nasugbu at magpababa sa KC Hillcrest Golf Club (dating Evercrest), saka mag-tricycle o maglakad papunta sa registration. Ayon sa isang trip report noong 2022, 2 hanggang 3 oras ang biyahe ng bus mula Maynila. Sa OpenStreetMap, mga 3.4 km ang layo ng tuktok mula sa jump-off kung sa New Trail, at 4.2 km kung sa Old Trail.',
   'transitpinas.com (2022), lakbaypinas.com (2026), openstreetmap.org (2026)',
   '[{"title": "Mt. Batulao, Batangas | Into the Jagged Peaks of Nasugbu (TransitPinas)", "url": "https://transitpinas.com/batulao-nasugbu-batangas/", "published": "2022-07-07", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "OpenStreetMap: Mt. Batulao relation 3350629 and nearby nodes (Overpass, data as of 2026-10-09)", "url": "https://www.openstreetmap.org/relation/3350629", "published": "2026-10-09", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-getting-there-2-en', 'batulao', 'getting_there', 'en',
   'Batulao has two Trails that share the first stretch from the jump-off and split at a fork past the roadside huts. The New Trail runs west over a ridge of numbered peaks and is described as the gentler choice for first-timers. The Old Trail runs east past Camps 1 to 9 and ends in a steep roped climb. A common plan, reported in 2026, is to go up the New Trail and down the Old Trail.',
   'lakbaypinas.com (2026), pinoymountaineer.com (2013), s1expeditions.com (2012)',
   '[{"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "Mt. Batulao (811+) (Pinoy Mountaineer; last updated 2013-02-16, with a November 2015 note)", "url": "https://www.pinoymountaineer.com/?p=1342", "published": "2013-02-16", "accessed": "2026-10-10"}, {"title": "Conquering Mt. Batulao at 811 MASL (S1 Expeditions; the trip whose GPS trace became the OSM Trails)", "url": "https://www.s1expeditions.com/2012/11/conquering-mt-batulao-at-811masl.html", "published": "2012-11-26", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-getting-there-2-fil', 'batulao', 'getting_there', 'fil',
   'Dalawa ang Trail sa Batulao. Iisa ang daan nila mula sa jump-off hanggang sa sangandaan lampas sa mga kubo, saka sila naghihiwalay. Pakanluran ang New Trail, dumadaan sa sunod-sunod na peak sa tagaytay ng bundok, at sinasabing mas madali para sa mga first-timer. Pasilangan ang Old Trail, dumadaan sa Camp 1 hanggang 9, at nagtatapos sa matarik na akyat na may lubid. Ayon sa ulat noong 2026, karaniwang umaakyat sa New Trail at bumababa sa Old Trail.',
   'lakbaypinas.com (2026), pinoymountaineer.com (2013), s1expeditions.com (2012)',
   '[{"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "Mt. Batulao (811+) (Pinoy Mountaineer; last updated 2013-02-16, with a November 2015 note)", "url": "https://www.pinoymountaineer.com/?p=1342", "published": "2013-02-16", "accessed": "2026-10-10"}, {"title": "Conquering Mt. Batulao at 811 MASL (S1 Expeditions; the trip whose GPS trace became the OSM Trails)", "url": "https://www.s1expeditions.com/2012/11/conquering-mt-batulao-at-811masl.html", "published": "2012-11-26", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-registration-1-en', 'batulao', 'registration', 'en',
   'Fees at Batulao change often and reports disagree, so bring cash and confirm on arrival. As of June 2022, one trip report paid a combined barangay and ecotourism fee of PHP 140 per person at the registration area, plus PHP 25 for a shower and PHP 100 to park a car. A 2026 guide reported the same PHP 140 at the jump-off kiosk, plus PHP 20 at Camp 8 on the New Trail and PHP 40 where the Old Trail descends: about PHP 200 for a full traverse.',
   'transitpinas.com (2022), lakbaypinas.com (2026)',
   '[{"title": "Mt. Batulao, Batangas | Into the Jagged Peaks of Nasugbu (TransitPinas)", "url": "https://transitpinas.com/batulao-nasugbu-batangas/", "published": "2022-07-07", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-registration-1-fil', 'batulao', 'registration', 'fil',
   'Madalas magbago ang bayarin sa Batulao at hindi magkakatugma ang mga ulat, kaya magdala ng cash at magtanong pagdating. Noong Hunyo 2022, ayon sa isang trip report, PHP 140 bawat tao ang pinagsamang barangay at ecotourism fee sa registration, dagdag ang PHP 25 sa paliligo at PHP 100 sa parking ng kotse. Ayon sa isang gabay noong 2026, PHP 140 pa rin sa kiosk sa jump-off, may PHP 20 sa Camp 8 ng New Trail at PHP 40 sa pababa ng Old Trail: mga PHP 200 sa buong traverse.',
   'transitpinas.com (2022), lakbaypinas.com (2026)',
   '[{"title": "Mt. Batulao, Batangas | Into the Jagged Peaks of Nasugbu (TransitPinas)", "url": "https://transitpinas.com/batulao-nasugbu-batangas/", "published": "2022-07-07", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-registration-2-en', 'batulao', 'registration', 'en',
   'Whether a guide is required has been disputed for years. In 2015 the Nasugbu tourism office said guides were not required, yet hikers reported being made to hire one at the trailhead. A 2026 guide says a local guide is now mandatory at registration, at PHP 800 per group of up to five for a day hike. A 2024 guide gave the same price but called guides optional. Plan to hire one, and agree on the price before you start.',
   'pinoymountaineer.com (2015), lakbaypinas.com (2026), thetravellingfoxes.com (2024)',
   '[{"title": "Mt. Batulao: Hikers forced to get guides despite not being required (Pinoy Mountaineer)", "url": "https://www.pinoymountaineer.com/?p=7798", "published": "2015-11-30", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "Mt. Batulao (New Trail): A Scenic Hike for Beginners and Beyond (The Travelling Foxes)", "url": "https://www.thetravellingfoxes.com/post/mt-batulao-new-trail", "published": "2024-08-26", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-registration-2-fil', 'batulao', 'registration', 'fil',
   'Matagal nang pinagtatalunan kung kailangan ng guide sa Batulao. Noong 2015, sinabi ng tourism office ng Nasugbu na hindi ito kailangan, pero may mga hiker na pinilit kumuha ng guide sa trailhead. Ayon sa isang gabay noong 2026, required na ang local guide sa pagpaparehistro, PHP 800 bawat grupo na hanggang lima para sa day hike. Ganoon din ang presyo sa isang gabay noong 2024, pero optional daw. Maghandang kumuha ng guide at magkasundo muna sa presyo bago umakyat.',
   'pinoymountaineer.com (2015), lakbaypinas.com (2026), thetravellingfoxes.com (2024)',
   '[{"title": "Mt. Batulao: Hikers forced to get guides despite not being required (Pinoy Mountaineer)", "url": "https://www.pinoymountaineer.com/?p=7798", "published": "2015-11-30", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "Mt. Batulao (New Trail): A Scenic Hike for Beginners and Beyond (The Travelling Foxes)", "url": "https://www.thetravellingfoxes.com/post/mt-batulao-new-trail", "published": "2024-08-26", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-registration-3-en', 'batulao', 'registration', 'en',
   'Register before you start the hike. A 2026 guide reported that the main registration booth at the jump-off opens at 5:00 AM, and that hikers starting earlier register with the caretakers at Camp 1 on the Old Trail or Camp 8 on the New Trail, who stay there around the clock. It also reported that fees are cash only, so do not rely on GCash or Maya. On OpenStreetMap, the registration booth is on the access road about 120 m before the trailhead.',
   'lakbaypinas.com (2026), openstreetmap.org (2026)',
   '[{"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "OpenStreetMap: Mt. Batulao relation 3350629 and nearby nodes (Overpass, data as of 2026-10-09)", "url": "https://www.openstreetmap.org/relation/3350629", "published": "2026-10-09", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-registration-3-fil', 'batulao', 'registration', 'fil',
   'Magparehistro bago magsimulang umakyat. Ayon sa isang gabay noong 2026, alas-5:00 ng umaga nagbubukas ang pangunahing registration booth sa jump-off. Ang mga mas maagang aakyat ay nagpaparehistro sa mga caretaker sa Camp 1 ng Old Trail o sa Camp 8 ng New Trail, na naroon buong araw at gabi. Cash lang daw ang tinatanggap, kaya huwag umasa sa GCash o Maya. Sa OpenStreetMap, nasa daan ang registration booth, mga 120 m bago ang trailhead.',
   'lakbaypinas.com (2026), openstreetmap.org (2026)',
   '[{"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "OpenStreetMap: Mt. Batulao relation 3350629 and nearby nodes (Overpass, data as of 2026-10-09)", "url": "https://www.openstreetmap.org/relation/3350629", "published": "2026-10-09", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-water-1-en', 'batulao', 'water', 'en',
   'There is no reliable water on the trail itself, so carry everything you need from the jump-off: 2 to 3 litres per person or more, and a 2026 guide says 3 litres at minimum. Older reports say the New Trail campsite sold water that locals carried up from a river about 30 minutes away. Huts near the fork have sold buko juice and halo-halo, mostly on weekends. Treat these as a bonus, never as your water plan.',
   'pinoymountaineer.com (2013), lakbaypinas.com (2026), chasejase.com (2017), transitpinas.com (2022), s1expeditions.com (2012), openstreetmap.org (2026)',
   '[{"title": "Mt. Batulao (811+) (Pinoy Mountaineer; last updated 2013-02-16, with a November 2015 note)", "url": "https://www.pinoymountaineer.com/?p=1342", "published": "2013-02-16", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "Mt. Batulao travel guide (Chase Jase; undated, images from February 2017)", "url": "https://chasejase.com/batulao-nasugbu-batangas-guide/", "published": "2017-02 (approx.)", "accessed": "2026-10-10"}, {"title": "Mt. Batulao, Batangas | Into the Jagged Peaks of Nasugbu (TransitPinas)", "url": "https://transitpinas.com/batulao-nasugbu-batangas/", "published": "2022-07-07", "accessed": "2026-10-10"}, {"title": "Conquering Mt. Batulao at 811 MASL (S1 Expeditions; the trip whose GPS trace became the OSM Trails)", "url": "https://www.s1expeditions.com/2012/11/conquering-mt-batulao-at-811masl.html", "published": "2012-11-26", "accessed": "2026-10-10"}, {"title": "OpenStreetMap: Mt. Batulao relation 3350629 and nearby nodes (Overpass, data as of 2026-10-09)", "url": "https://www.openstreetmap.org/relation/3350629", "published": "2026-10-09", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-water-1-fil', 'batulao', 'water', 'fil',
   'Walang maaasahang tubig sa mismong trail, kaya dalhin na mula sa jump-off ang lahat ng kailangan mo: 2 hanggang 3 litro o higit pa bawat tao, at 3 litro ang pinakamababa ayon sa isang gabay noong 2026. Sabi ng mga lumang ulat, nagbebenta ng tubig sa campsite ng New Trail na iniakyat mula sa ilog na mga 30 minuto ang layo. May mga kubo sa may sangandaan na nagtitinda ng buko juice at halo-halo, kadalasan tuwing weekend. Dagdag lang ito, hindi ang plano mo sa tubig.',
   'pinoymountaineer.com (2013), lakbaypinas.com (2026), chasejase.com (2017), transitpinas.com (2022), s1expeditions.com (2012), openstreetmap.org (2026)',
   '[{"title": "Mt. Batulao (811+) (Pinoy Mountaineer; last updated 2013-02-16, with a November 2015 note)", "url": "https://www.pinoymountaineer.com/?p=1342", "published": "2013-02-16", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "Mt. Batulao travel guide (Chase Jase; undated, images from February 2017)", "url": "https://chasejase.com/batulao-nasugbu-batangas-guide/", "published": "2017-02 (approx.)", "accessed": "2026-10-10"}, {"title": "Mt. Batulao, Batangas | Into the Jagged Peaks of Nasugbu (TransitPinas)", "url": "https://transitpinas.com/batulao-nasugbu-batangas/", "published": "2022-07-07", "accessed": "2026-10-10"}, {"title": "Conquering Mt. Batulao at 811 MASL (S1 Expeditions; the trip whose GPS trace became the OSM Trails)", "url": "https://www.s1expeditions.com/2012/11/conquering-mt-batulao-at-811masl.html", "published": "2012-11-26", "accessed": "2026-10-10"}, {"title": "OpenStreetMap: Mt. Batulao relation 3350629 and nearby nodes (Overpass, data as of 2026-10-09)", "url": "https://www.openstreetmap.org/relation/3350629", "published": "2026-10-09", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-water-2-en', 'batulao', 'water', 'en',
   'OpenStreetMap marks two springs beside Camp 1 on the Old Trail. A 2012 trip report described Camp 1''s water as only "semi"-potable, drawn from a stream about 300 m away, and a 2026 guide called the small stream near Camp 1 seasonal and unsafe to drink without filtering. If you use it, filter and disinfect it first. No natural water source is reported on the New Trail or on the upper mountain.',
   'openstreetmap.org (2026), s1expeditions.com (2012), lakbaypinas.com (2026), pinoymountaineer.com (2013)',
   '[{"title": "OpenStreetMap: Mt. Batulao relation 3350629 and nearby nodes (Overpass, data as of 2026-10-09)", "url": "https://www.openstreetmap.org/relation/3350629", "published": "2026-10-09", "accessed": "2026-10-10"}, {"title": "Conquering Mt. Batulao at 811 MASL (S1 Expeditions; the trip whose GPS trace became the OSM Trails)", "url": "https://www.s1expeditions.com/2012/11/conquering-mt-batulao-at-811masl.html", "published": "2012-11-26", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "Mt. Batulao (811+) (Pinoy Mountaineer; last updated 2013-02-16, with a November 2015 note)", "url": "https://www.pinoymountaineer.com/?p=1342", "published": "2013-02-16", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-water-2-fil', 'batulao', 'water', 'fil',
   'May dalawang bukal na nakamarka sa OpenStreetMap sa tabi ng Camp 1 sa Old Trail. Ayon sa isang trip report noong 2012, "semi"-potable lang ang tubig sa Camp 1, na galing sa sapa na mga 300 m ang layo. Sabi naman ng isang gabay noong 2026, pana-panahon lang ang maliit na sapa malapit sa Camp 1 at hindi ligtas inumin nang hindi sinasala. Kung gagamitin ito, salain at linisin muna. Walang naiulat na natural na mapagkukunan ng tubig sa New Trail o sa itaas ng bundok.',
   'openstreetmap.org (2026), s1expeditions.com (2012), lakbaypinas.com (2026), pinoymountaineer.com (2013)',
   '[{"title": "OpenStreetMap: Mt. Batulao relation 3350629 and nearby nodes (Overpass, data as of 2026-10-09)", "url": "https://www.openstreetmap.org/relation/3350629", "published": "2026-10-09", "accessed": "2026-10-10"}, {"title": "Conquering Mt. Batulao at 811 MASL (S1 Expeditions; the trip whose GPS trace became the OSM Trails)", "url": "https://www.s1expeditions.com/2012/11/conquering-mt-batulao-at-811masl.html", "published": "2012-11-26", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "Mt. Batulao (811+) (Pinoy Mountaineer; last updated 2013-02-16, with a November 2015 note)", "url": "https://www.pinoymountaineer.com/?p=1342", "published": "2013-02-16", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-campsites-1-en', 'batulao', 'campsites', 'en',
   'Camping on the summit is not allowed, according to a 2022 trip report. The designated campsite is Camp 1, at the foot of the Old Trail, about 3.3 km from the jump-off along that trail. It has the largest tent area, and reports mention toilets and a store there. A 2026 guide reported a camping fee of PHP 30 per person per night and tent rental at PHP 350 a night; confirm both with the caretakers.',
   'transitpinas.com (2022), s1expeditions.com (2012), outdoorholiday.com (2025), lakbaypinas.com (2026), openstreetmap.org (2026)',
   '[{"title": "Mt. Batulao, Batangas | Into the Jagged Peaks of Nasugbu (TransitPinas)", "url": "https://transitpinas.com/batulao-nasugbu-batangas/", "published": "2022-07-07", "accessed": "2026-10-10"}, {"title": "Conquering Mt. Batulao at 811 MASL (S1 Expeditions; the trip whose GPS trace became the OSM Trails)", "url": "https://www.s1expeditions.com/2012/11/conquering-mt-batulao-at-811masl.html", "published": "2012-11-26", "accessed": "2026-10-10"}, {"title": "Mount Batulao Day Hike: Complete Guide to Batangas'' Famous Ridgeline Trail (Outdoor Holiday)", "url": "https://outdoorholiday.com/mount-batulao-day-hike/", "published": "2025-09-22", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "OpenStreetMap: Mt. Batulao relation 3350629 and nearby nodes (Overpass, data as of 2026-10-09)", "url": "https://www.openstreetmap.org/relation/3350629", "published": "2026-10-09", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-campsites-1-fil', 'batulao', 'campsites', 'fil',
   'Bawal magkampo sa tuktok, ayon sa isang trip report noong 2022. Ang itinakdang kampuhan ay ang Camp 1, sa paanan ng Old Trail, mga 3.3 km mula sa jump-off sa trail na iyon. Ito ang may pinakamalawak na puwesto para sa tent, at may naiulat na CR at tindahan doon. Ayon sa isang gabay noong 2026, PHP 30 bawat tao kada gabi ang bayad sa pagkampo at PHP 350 kada gabi ang upa ng tent. Kumpirmahin ang dalawa sa mga caretaker.',
   'transitpinas.com (2022), s1expeditions.com (2012), outdoorholiday.com (2025), lakbaypinas.com (2026), openstreetmap.org (2026)',
   '[{"title": "Mt. Batulao, Batangas | Into the Jagged Peaks of Nasugbu (TransitPinas)", "url": "https://transitpinas.com/batulao-nasugbu-batangas/", "published": "2022-07-07", "accessed": "2026-10-10"}, {"title": "Conquering Mt. Batulao at 811 MASL (S1 Expeditions; the trip whose GPS trace became the OSM Trails)", "url": "https://www.s1expeditions.com/2012/11/conquering-mt-batulao-at-811masl.html", "published": "2012-11-26", "accessed": "2026-10-10"}, {"title": "Mount Batulao Day Hike: Complete Guide to Batangas'' Famous Ridgeline Trail (Outdoor Holiday)", "url": "https://outdoorholiday.com/mount-batulao-day-hike/", "published": "2025-09-22", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "OpenStreetMap: Mt. Batulao relation 3350629 and nearby nodes (Overpass, data as of 2026-10-09)", "url": "https://www.openstreetmap.org/relation/3350629", "published": "2026-10-09", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-campsites-2-en', 'batulao', 'campsites', 'en',
   'On the New Trail, the campsite and fee checkpoint is at Peak 8, about 2.5 km from the jump-off; hikers and guides often call it Camp 8. It has had shelters and is a usual rest and lunch stop. A 2026 guide described it as the New Trail''s main rest stop and second registration point, with caretakers there day and night. Do not confuse it with the Old Trail''s Camp 8, which is near the summit.',
   's1expeditions.com (2012), lakbaypinas.com (2026), awanderfulsole.com (2024), chasejase.com (2017), openstreetmap.org (2026)',
   '[{"title": "Conquering Mt. Batulao at 811 MASL (S1 Expeditions; the trip whose GPS trace became the OSM Trails)", "url": "https://www.s1expeditions.com/2012/11/conquering-mt-batulao-at-811masl.html", "published": "2012-11-26", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "MT. BATULAO: (Updated 2024) Day Hike Guide for Beginners (A Wanderful Sole)", "url": "https://awanderfulsole.com/mt-batulao-dayhike-guide-beginners/", "published": "2024-09-26", "accessed": "2026-10-10"}, {"title": "Mt. Batulao travel guide (Chase Jase; undated, images from February 2017)", "url": "https://chasejase.com/batulao-nasugbu-batangas-guide/", "published": "2017-02 (approx.)", "accessed": "2026-10-10"}, {"title": "OpenStreetMap: Mt. Batulao relation 3350629 and nearby nodes (Overpass, data as of 2026-10-09)", "url": "https://www.openstreetmap.org/relation/3350629", "published": "2026-10-09", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-campsites-2-fil', 'batulao', 'campsites', 'fil',
   'Sa New Trail, nasa Peak 8 ang kampuhan at bayaran, mga 2.5 km mula sa jump-off. Madalas itong tawaging Camp 8 ng mga hiker at guide. May mga silungan dito noon at karaniwang pahingahan at kainan ng tanghalian. Ayon sa isang gabay noong 2026, ito ang pangunahing pahingahan ng New Trail at pangalawang registration, at may caretaker dito araw at gabi. Huwag itong ipagkamali sa Camp 8 ng Old Trail, na malapit na sa tuktok.',
   's1expeditions.com (2012), lakbaypinas.com (2026), awanderfulsole.com (2024), chasejase.com (2017), openstreetmap.org (2026)',
   '[{"title": "Conquering Mt. Batulao at 811 MASL (S1 Expeditions; the trip whose GPS trace became the OSM Trails)", "url": "https://www.s1expeditions.com/2012/11/conquering-mt-batulao-at-811masl.html", "published": "2012-11-26", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "MT. BATULAO: (Updated 2024) Day Hike Guide for Beginners (A Wanderful Sole)", "url": "https://awanderfulsole.com/mt-batulao-dayhike-guide-beginners/", "published": "2024-09-26", "accessed": "2026-10-10"}, {"title": "Mt. Batulao travel guide (Chase Jase; undated, images from February 2017)", "url": "https://chasejase.com/batulao-nasugbu-batangas-guide/", "published": "2017-02 (approx.)", "accessed": "2026-10-10"}, {"title": "OpenStreetMap: Mt. Batulao relation 3350629 and nearby nodes (Overpass, data as of 2026-10-09)", "url": "https://www.openstreetmap.org/relation/3350629", "published": "2026-10-09", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-hazards-1-en', 'batulao', 'hazards', 'en',
   'Most of Batulao is open grassland with almost no shade. Trip reports advise starting by 6 AM because the trail is fully exposed to the sun from about 10 AM, and bringing sun protection. Strong wind is common on the open ridges and can push you off balance on narrow sections. The weather can change quickly, so carry rain gear even on a clear morning.',
   'awanderfulsole.com (2024), lakbaypinas.com (2026), transitpinas.com (2022), thetravellingfoxes.com (2024)',
   '[{"title": "MT. BATULAO: (Updated 2024) Day Hike Guide for Beginners (A Wanderful Sole)", "url": "https://awanderfulsole.com/mt-batulao-dayhike-guide-beginners/", "published": "2024-09-26", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "Mt. Batulao, Batangas | Into the Jagged Peaks of Nasugbu (TransitPinas)", "url": "https://transitpinas.com/batulao-nasugbu-batangas/", "published": "2022-07-07", "accessed": "2026-10-10"}, {"title": "Mt. Batulao (New Trail): A Scenic Hike for Beginners and Beyond (The Travelling Foxes)", "url": "https://www.thetravellingfoxes.com/post/mt-batulao-new-trail", "published": "2024-08-26", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-hazards-1-fil', 'batulao', 'hazards', 'fil',
   'Halos buong Batulao ay bukas na damuhan na halos walang lilim. Payo ng mga trip report na magsimula bago mag-alas-6 ng umaga dahil pagsapit ng mga alas-10, wala nang masisilungan sa init ng araw. Magdala ng pananggalang sa araw. Malakas ang hangin sa mga bukas na tagaytay at puwede kang matumba sa makikitid na bahagi. Mabilis magbago ang panahon, kaya magdala ng kapote kahit maaliwalas sa umaga.',
   'awanderfulsole.com (2024), lakbaypinas.com (2026), transitpinas.com (2022), thetravellingfoxes.com (2024)',
   '[{"title": "MT. BATULAO: (Updated 2024) Day Hike Guide for Beginners (A Wanderful Sole)", "url": "https://awanderfulsole.com/mt-batulao-dayhike-guide-beginners/", "published": "2024-09-26", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "Mt. Batulao, Batangas | Into the Jagged Peaks of Nasugbu (TransitPinas)", "url": "https://transitpinas.com/batulao-nasugbu-batangas/", "published": "2022-07-07", "accessed": "2026-10-10"}, {"title": "Mt. Batulao (New Trail): A Scenic Hike for Beginners and Beyond (The Travelling Foxes)", "url": "https://www.thetravellingfoxes.com/post/mt-batulao-new-trail", "published": "2024-08-26", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-hazards-2-en', 'batulao', 'hazards', 'en',
   'The last climb to the summit is steep. The Old Trail has fixed ropes between Camp 8 and the summit, and short rappel sections are reported on both Trails. Watch for loose rocks, including stones knocked down by hikers above you. Ropes get slippery when wet. A 2026 guide says most incidents happen while descending the Old Trail, so take extra care on the way down.',
   'pinoymountaineer.com (2013), transitpinas.com (2022), chasejase.com (2017), lakbaypinas.com (2026)',
   '[{"title": "Mt. Batulao (811+) (Pinoy Mountaineer; last updated 2013-02-16, with a November 2015 note)", "url": "https://www.pinoymountaineer.com/?p=1342", "published": "2013-02-16", "accessed": "2026-10-10"}, {"title": "Mt. Batulao, Batangas | Into the Jagged Peaks of Nasugbu (TransitPinas)", "url": "https://transitpinas.com/batulao-nasugbu-batangas/", "published": "2022-07-07", "accessed": "2026-10-10"}, {"title": "Mt. Batulao travel guide (Chase Jase; undated, images from February 2017)", "url": "https://chasejase.com/batulao-nasugbu-batangas-guide/", "published": "2017-02 (approx.)", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-hazards-2-fil', 'batulao', 'hazards', 'fil',
   'Matarik ang huling akyat papunta sa tuktok. May nakakabit na lubid sa Old Trail mula Camp 8 hanggang tuktok, at may maiikling bahaging pa-rappel na naiulat sa parehong Trail. Mag-ingat sa maluluwag na bato, pati sa mga batong natatabig ng mga hiker sa itaas mo. Dumudulas ang lubid kapag basa. Ayon sa isang gabay noong 2026, kadalasang sa pagbaba sa Old Trail nangyayari ang aksidente, kaya doblehin ang ingat pababa.',
   'pinoymountaineer.com (2013), transitpinas.com (2022), chasejase.com (2017), lakbaypinas.com (2026)',
   '[{"title": "Mt. Batulao (811+) (Pinoy Mountaineer; last updated 2013-02-16, with a November 2015 note)", "url": "https://www.pinoymountaineer.com/?p=1342", "published": "2013-02-16", "accessed": "2026-10-10"}, {"title": "Mt. Batulao, Batangas | Into the Jagged Peaks of Nasugbu (TransitPinas)", "url": "https://transitpinas.com/batulao-nasugbu-batangas/", "published": "2022-07-07", "accessed": "2026-10-10"}, {"title": "Mt. Batulao travel guide (Chase Jase; undated, images from February 2017)", "url": "https://chasejase.com/batulao-nasugbu-batangas-guide/", "published": "2017-02 (approx.)", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-hazards-3-en', 'batulao', 'hazards', 'en',
   'On the New Trail, the ridge from Peak 8 to the summit runs beside a ravine. In February 2012 a first-time hiker died after falling at Peak 8 while taking photos, so stay on the path and secure your footing before taking pictures. Near Peak 9 there is loose rock and a known wrong turn: a 2012 trip report and an OpenStreetMap note both say not to climb the slope on your right. Keep left.',
   'pinoymountaineer.com (2013), s1expeditions.com (2012), lakbaypinas.com (2026), openstreetmap.org (2026)',
   '[{"title": "Mt. Batulao (811+) (Pinoy Mountaineer; last updated 2013-02-16, with a November 2015 note)", "url": "https://www.pinoymountaineer.com/?p=1342", "published": "2013-02-16", "accessed": "2026-10-10"}, {"title": "Conquering Mt. Batulao at 811 MASL (S1 Expeditions; the trip whose GPS trace became the OSM Trails)", "url": "https://www.s1expeditions.com/2012/11/conquering-mt-batulao-at-811masl.html", "published": "2012-11-26", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "OpenStreetMap: Mt. Batulao relation 3350629 and nearby nodes (Overpass, data as of 2026-10-09)", "url": "https://www.openstreetmap.org/relation/3350629", "published": "2026-10-09", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-hazards-3-fil', 'batulao', 'hazards', 'fil',
   'Sa New Trail, may bangin sa tabi ng tagaytay mula Peak 8 hanggang tuktok. Noong Pebrero 2012, may unang beses na hiker na namatay matapos mahulog sa Peak 8 habang kumukuha ng litrato. Manatili sa daan at siguraduhing matatag ang tapak bago kumuha ng litrato. Malapit sa Peak 9, may maluluwag na bato at kilalang maling liko: ayon sa isang trip report noong 2012 at sa isang tala sa OpenStreetMap, huwag akyatin ang dalisdis sa kanan mo. Manatili sa kaliwa.',
   'pinoymountaineer.com (2013), s1expeditions.com (2012), lakbaypinas.com (2026), openstreetmap.org (2026)',
   '[{"title": "Mt. Batulao (811+) (Pinoy Mountaineer; last updated 2013-02-16, with a November 2015 note)", "url": "https://www.pinoymountaineer.com/?p=1342", "published": "2013-02-16", "accessed": "2026-10-10"}, {"title": "Conquering Mt. Batulao at 811 MASL (S1 Expeditions; the trip whose GPS trace became the OSM Trails)", "url": "https://www.s1expeditions.com/2012/11/conquering-mt-batulao-at-811masl.html", "published": "2012-11-26", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "OpenStreetMap: Mt. Batulao relation 3350629 and nearby nodes (Overpass, data as of 2026-10-09)", "url": "https://www.openstreetmap.org/relation/3350629", "published": "2026-10-09", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-hazards-4-en', 'batulao', 'hazards', 'en',
   'From June to October the trail turns muddy and slippery after rain, and in the dry months it is dusty and windy. Brushfires are common on Batulao''s grass slopes in the dry season; a large burn was reported in March 2013, and Pinoy Mountaineer has urged hikers to take care on grassy mountains in summer. Never leave a fire or a lit cigarette on the mountain.',
   'pinoymountaineer.com (2013), transitpinas.com (2022), pinoymountaineer.com (2013)',
   '[{"title": "Mt. Batulao (811+) (Pinoy Mountaineer; last updated 2013-02-16, with a November 2015 note)", "url": "https://www.pinoymountaineer.com/?p=1342", "published": "2013-02-16", "accessed": "2026-10-10"}, {"title": "Mt. Batulao, Batangas | Into the Jagged Peaks of Nasugbu (TransitPinas)", "url": "https://transitpinas.com/batulao-nasugbu-batangas/", "published": "2022-07-07", "accessed": "2026-10-10"}, {"title": "Hiking matters #329: Yet again, Batulao / My take on brushfires (Pinoy Mountaineer)", "url": "https://www.pinoymountaineer.com/?p=282", "published": "2013-03-20", "accessed": "2026-10-10"}]'::jsonb, '2022-07'),
  ('batulao-hazards-4-fil', 'batulao', 'hazards', 'fil',
   'Mula Hunyo hanggang Oktubre, maputik at madulas ang trail pagkatapos umulan. Sa tag-araw naman, maalikabok at mahangin. Karaniwan ang sunog sa damuhan ng Batulao tuwing tag-araw; may malaking sunog na naiulat noong Marso 2013, at nanawagan ang Pinoy Mountaineer na mag-ingat sa mga madamong bundok tuwing tag-init. Huwag mag-iwan ng apoy o nakasinding sigarilyo sa bundok.',
   'pinoymountaineer.com (2013), transitpinas.com (2022), pinoymountaineer.com (2013)',
   '[{"title": "Mt. Batulao (811+) (Pinoy Mountaineer; last updated 2013-02-16, with a November 2015 note)", "url": "https://www.pinoymountaineer.com/?p=1342", "published": "2013-02-16", "accessed": "2026-10-10"}, {"title": "Mt. Batulao, Batangas | Into the Jagged Peaks of Nasugbu (TransitPinas)", "url": "https://transitpinas.com/batulao-nasugbu-batangas/", "published": "2022-07-07", "accessed": "2026-10-10"}, {"title": "Hiking matters #329: Yet again, Batulao / My take on brushfires (Pinoy Mountaineer)", "url": "https://www.pinoymountaineer.com/?p=282", "published": "2013-03-20", "accessed": "2026-10-10"}]'::jsonb, '2022-07'),
  ('batulao-hazards-5-en', 'batulao', 'hazards', 'en',
   'A 2022 trip report said mobile signal and data worked along the whole trail, so you may be able to call for help, but do not depend on it. In an emergency, alert your guide and the caretakers at Camp 1 or Camp 8, who are reported to stay there day and night. Pinoy Mountaineer listed the Nasugbu Police Station as (043) 931-9952; that number dates from 2013 and may have changed.',
   'transitpinas.com (2022), lakbaypinas.com (2026), pinoymountaineer.com (2013)',
   '[{"title": "Mt. Batulao, Batangas | Into the Jagged Peaks of Nasugbu (TransitPinas)", "url": "https://transitpinas.com/batulao-nasugbu-batangas/", "published": "2022-07-07", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "Mt. Batulao (811+) (Pinoy Mountaineer; last updated 2013-02-16, with a November 2015 note)", "url": "https://www.pinoymountaineer.com/?p=1342", "published": "2013-02-16", "accessed": "2026-10-10"}]'::jsonb, '2026-05'),
  ('batulao-hazards-5-fil', 'batulao', 'hazards', 'fil',
   'Ayon sa isang trip report noong 2022, may signal at data sa buong trail, kaya baka makatawag ka ng tulong, pero huwag itong asahan. Kapag may emergency, sabihan agad ang guide at ang mga caretaker sa Camp 1 o Camp 8, na naiulat na naroon araw at gabi. Nakalista sa Pinoy Mountaineer ang Nasugbu Police Station sa (043) 931-9952, pero mula pa ito noong 2013 at baka nagbago na.',
   'transitpinas.com (2022), lakbaypinas.com (2026), pinoymountaineer.com (2013)',
   '[{"title": "Mt. Batulao, Batangas | Into the Jagged Peaks of Nasugbu (TransitPinas)", "url": "https://transitpinas.com/batulao-nasugbu-batangas/", "published": "2022-07-07", "accessed": "2026-10-10"}, {"title": "Ultimate Guide To Mt. Batulao In Batangas 2026 (LakbayPinas; author reports climbing in May 2026)", "url": "https://lakbaypinas.com/mt-batulao-masl-difficulty-hike-height-location/", "published": "2026-09-02", "accessed": "2026-10-10"}, {"title": "Mt. Batulao (811+) (Pinoy Mountaineer; last updated 2013-02-16, with a November 2015 note)", "url": "https://www.pinoymountaineer.com/?p=1342", "published": "2013-02-16", "accessed": "2026-10-10"}]'::jsonb, '2026-05');

